before.code:
int a[] = {2, 4, 6};
int total = 0;
for (int i = 0; i < 3; i++)
    total += a[i];
printf("%d", total);

after.code:
int a[] = {2, 4, 6};
int total = 0;
for (int i = 1; i < 3; i++)
    total += a[i];
printf("%d", total);

before.code:
void change(int x) { x = 9; }

// main 내부
int a = 1;
change(a);
printf("%d", a);

after.code:
void change(int *p) { *p = 9; }

// main 내부
int a = 1;
change(&a);
printf("%d", a);

common:
typedef struct Node {
    int value;
    struct Node *left, *right;
} Node;

before.code:
void visit(Node *n) {
    if (n == NULL) return;
    printf("%d ", n->value);
    visit(n->left);
    visit(n->right);
}

after.code:
void visit(Node *n) {
    if (n == NULL) return;
    visit(n->left);
    visit(n->right);
    printf("%d ", n->value);
}

common:
typedef struct Node { int value; struct Node *next; } Node;
// main 내부의 공통 준비: a → b → c
Node a = {1, NULL}, b = {2, NULL}, c = {3, NULL};
a.next = &b; b.next = &c;

before.code:
a.value = 3;
for (Node *p = &a; p != NULL; p = p->next)
    printf("%d ", p->value);

after.code:
a.next = &c;
for (Node *p = &a; p != NULL; p = p->next)
    printf("%d ", p->value);
